        return grid
    rows = len(grid)
    cols = len(grid[0])
    if cols % 2 != 0:
        return grid
    half = cols // 2
    block_size = half                     # square blocks (e.g. 4×4, 5×5, …)

    for br in range(0, rows, block_size):
        if br + block_size > rows:
            break

        # collect statistics for the mapping
        left_to_right = {}
