            row = grid[br + i]
            left = row[:half]
            right = row[half:]
            for j in range(half):
                lv = left[j]
                rv = right[j]
                if lv not in left_to_right:
                    left_to_right[lv] = Counter()
                left_to_right[lv][rv] += 1

        # choose the most frequent right value for each left value
        mapping = {lv: cnt.most_common(1)[0][0] for lv, cnt in left_to_right.items()}

        # rewrite the right half using the inferred mapping
        for i in range(block_size):
            row = grid[br + i]
            left = row[:half]
